<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../services/TicketService.php';Auth::requireLogin();if(!TicketService::canManage()&&!Auth::can('ticketing.categories','edit')){http_response_code(403);exit('دسترسی مدیریت دسته‌بندی‌ها فعال نیست.');}if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان دسته الزامی است.');$data=[$title,trim((string)($_POST['description']??'')),(int)($_POST['assigned_unit_id']??0)?:null,(int)($_POST['default_assignee_user_id']??0)?:null,isset($_POST['active'])?1:0,max(0,(int)($_POST['sort_order']??0))];if($id)Database::execute('UPDATE ticket_categories SET title=?,description=?,assigned_unit_id=?,default_assignee_user_id=?,active=?,sort_order=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO ticket_categories(title,description,assigned_unit_id,default_assignee_user_id,active,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())',$data);flash('دسته‌بندی ذخیره شد.');}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Ticket category: '.$e->getMessage());flash('ذخیره دسته‌بندی انجام نشد.','danger');}redirect('/admin/ticket-categories.php');}$rows=TicketService::categories(false);$edit=!empty($_GET['edit'])?Database::fetch('SELECT * FROM ticket_categories WHERE id=?',[(int)$_GET['edit']]):null;$users=Database::fetchAll('SELECT id,name FROM users WHERE status="active" ORDER BY name');$units=Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY sort_order,title');$pageTitle='دسته‌بندی تیکت‌ها';require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><h1>دسته‌بندی تیکت‌ها</h1><p class="muted">ارجاع پیش‌فرض هر نوع درخواست</p></div><a class="btn" href="/admin/tickets.php">بازگشت</a></div><section class="card admin-form"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="grid grid-3"><label>عنوان<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>واحد پیش‌فرض<select name="assigned_unit_id"><option value="">بدون واحد</option><?php foreach($units as $item):?><option value="<?=$item['id']?>" <?=(int)($edit['assigned_unit_id']??0)===$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label>مسئول پیش‌فرض<select name="default_assignee_user_id"><option value="">بدون مسئول</option><?php foreach($users as $item):?><option value="<?=$item['id']?>" <?=(int)($edit['default_assignee_user_id']??0)===$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach?></select></label><label>ترتیب<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label><label><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label><label>شرح<input name="description" value="<?=e($edit['description']??'')?>"></label></div><button class="btn btn-primary">ذخیره</button></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>واحد</th><th>مسئول</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['title'])?></td><td><?=e($row['unit_title']?:'—')?></td><td><?=e($row['assignee_name']?:'—')?></td><td><?=$row['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$row['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
